import {CREATURES,CREATURE_BY_ID,REGION_BY_ID} from './rpg-data.js';
import {WANDS,WAND_BY_ID,LEGENDS,LEGEND_BY_ID,legendGoals,captureChance,parkPosition} from './magic-data.js';
import {createParkInterior} from './park-interior.js';
import {createMagicWorld} from './magic-world.js';

export function setupMagic(ctx){
 const {state,player,scene,body,modal,progress,store:rpg,fishing,toast}=ctx,$=s=>document.querySelector(s);
 const world=createMagicWorld({scene,player,state});let section='care',selectedWand=fishing.store.state.wand,notice='';
 const b=(action,text,extra='')=>`<button data-magic-action="${action}" ${extra}>${text}</button>`;
 const tab=document.createElement('button');tab.textContent='U-Speak park';tab.dataset.adTab='sanctuary';tab.onclick=()=>open();$('.rpg-tabs').append(tab);
 const wallet=()=>fishing.store.state;
 const interior=createParkInterior({...ctx,onService:name=>service(name)});
 function interact(){if(!ctx.allowedUi())return;if(!interior.active){const b=interior.entrance();if(b)interior.enter(b);return}const station=interior.nearby();if(station?.id==='exit')interior.leave();else if(station)service(station.id);}
 function service(name){if(!interior.active||!interior.at(name))return;if(interior.building.kind==='park'||name==='legends')return open(name);if(name==='bag'||name==='shop')return fishing.open(name);if(name==='flight')return ctx.openMap();if(name==='story')return ctx.openStory();if(name==='rest'){progress.healAll();interior.heal();toast('ゆっくり休んで、仲間全員の集中力が回復しました。');ctx.speak('Have a good rest!');return}ctx.buildingService?.(name);}
 function enter(){if(!ctx.allowedUi())return false;if(interior.active){if(interior.building.kind==='park')return true;interior.leave(true)}if(!world.goto())return false;return interior.enter();}
 function open(next='care'){if(!ctx.allowedUi())return;if(!progress.state.starter)return ctx.openJourney();section=next;ctx.useView('sanctuary');render();}
 function render(){const s=progress.state,w=wallet(),local=parkPosition(state.current),near=interior.active&&interior.building.kind==='park',service=near&&interior.at(section);body.innerHTML=`<div class="magic-heading"><div><div class="rpg-eyebrow">A PLACE TO RETURN TO</div><h2>U-Speak park</h2><p>仲間を休ませ、次の出会いへ。</p></div><div class="magic-wallet"><small>所持コイン</small><strong>◈ ${w.coins.toLocaleString()}</strong></div></div><nav class="magic-tabs" aria-label="U-Speak parkのサービス">${[['care','仲間の回復'],['wands','8つの魔法の杖'],['legends','伝説の書']].map(([id,name])=>b('section',name,`data-id="${id}" aria-pressed="${id===section}"`)).join('')}</nav><div class="magic-location"><span>${near?'✓ U-Speak parkにいます':local?REGION_BY_ID[state.current].name+'の拠点へ': '回復拠点はWillow IslandとRPGの10地域にあります'}</span>${!near?(local?b('visit','この島のparkに入る'):b('willow','✈ Willow Islandへ')):b('room','ロビーを歩く')}${near&&!service?b('counter','このカウンターへ移動'):''}</div><p class="magic-notice" role="status">${notice}</p>`;
 if(section==='care'){const damaged=rpg.state.caught.filter(id=>progress.health(id).hp<progress.health(id).max);body.innerHTML+=`<section class="magic-care"><div class="rpg-eyebrow">REST · RESTORE · RECONNECT</div><h3>「おかえりなさい。みんなを元気にしますね。」</h3><p>チームも待機中の仲間も、集中力を全回復。何度でも無料です。</p><div class="magic-health-grid">${s.team.map(id=>{const h=progress.health(id);return `<article><small>PARTNER</small><strong>${CREATURE_BY_ID[id].name}</strong><div class="ad-meter" role="progressbar" aria-label="${CREATURE_BY_ID[id].name}の集中力" aria-valuenow="${h.hp}" aria-valuemin="0" aria-valuemax="${h.max}"><i style="width:${h.hp/h.max*100}%"></i></div><span>${h.hp} / ${h.max} HP</span></article>`}).join('')}</div><div class="ad-action-row">${b('heal',service?'仲間全員を回復する · 無料':'回復カウンターで利用できます',`class="primary" ${service?'':'disabled'}`)}${b('team','チームを編成する')}</div><small>${damaged.length?damaged.length+'体が回復を待っています。':'みんな元気です。いつでも冒険に出発できます。'}</small></section><div class="ad-grid two"><section class="ad-box"><h3>魔法の杖アトリエ</h3><p>魚を売ったコインで、捕獲の魔法を強くしよう。杖は何度でも使えます。</p>${b('section','杖を見に行く →','data-id="wands"')}</section><section class="ad-box"><h3>10の伝説、10の約束</h3><p>各地の物語とリーグの紋章が、眠る守護者を呼び覚まします。</p>${b('section','伝説の書をひらく →','data-id="legends"')}</section></div>`;if(rpg.state.buddy)ctx.showCreature(rpg.state.buddy);}
 if(section==='wands'){const selected=WAND_BY_ID[selectedWand]||WANDS[0];ctx.showWand(selected.id);body.innerHTML+=`<section class="magic-wand-intro"><small>装備中：${WAND_BY_ID[w.wand].name}</small><h3>ことばを届ける、きみの杖。</h3><p>英語に3回正解して魔法を充填 → 杖を振って捕獲。失敗すると次の捕獲率が10ポイント上がり、4回失敗した後は100%になります。</p><p class="rpg-fine">表示は初回の捕獲率です。杖は消耗せず、ヒントを使っても捕獲率は同じです。</p></section><div class="magic-wands">${WANDS.map((wand,i)=>{const owned=w.wands.includes(wand.id),equipped=w.wand===wand.id;return `<article class="magic-wand ${selected.id===wand.id?'selected':''}" style="--wand:#${wand.color.toString(16).padStart(6,'0')}"><div class="magic-wand-rank">${String(i+1).padStart(2,'0')}<small>${wand.en}</small></div><div><h3>${wand.name}</h3><p>${wand.description}</p><div class="magic-rates"><span>通常 <b>${captureChance(CREATURES[0],wand.id)}%</b></span><span>レア <b>${captureChance(CREATURES[7],wand.id)}%</b></span><span>伝説 <b>${captureChance(CREATURES[9],wand.id)}%</b></span><span>大伝説 <b>${captureChance(CREATURES[99],wand.id)}%</b></span></div></div><div class="magic-wand-actions"><strong>${owned?'所有済み':'◈ '+wand.price.toLocaleString()}</strong>${b('preview','3Dで見る',`data-id="${wand.id}"`)}${b(owned?'equip':'buy',equipped?'✓ 装備中':owned?'装備する':!service?'杖カウンターで購入':w.coins<wand.price?'あと '+(wand.price-w.coins)+' コイン':'購入して装備',`data-id="${wand.id}" ${equipped||!owned&&(!service||w.coins<wand.price)?'disabled':''}`)}</div></article>`}).join('')}</div>`;}
 if(section==='legends'){ctx.showCreature(LEGENDS[0].id);body.innerHTML+=`<p>伝説 ${LEGENDS.filter(l=>rpg.state.caught.includes(l.id)).length} / 10 体。条件を満たすと、その地域のフィールドに現れます。何度でも挑戦できます。</p><div class="magic-legends">${LEGENDS.map(l=>{const c=CREATURE_BY_ID[l.id],owned=rpg.state.caught.includes(l.id),goals=legendGoals(c,s),ready=owned||goals.every(g=>g.done);return `<article class="magic-legend ${l.grand?'grand':''}"><div class="rpg-eyebrow">${l.grand?'GRAND LEGEND':'REGIONAL GUARDIAN'} · NO.${c.number}</div><h3>${c.name}</h3><small>${l.title}</small><blockquote>“${l.oath}”</blockquote><ul>${goals.map(g=>`<li>${g.done?'✓':'○'} ${g.text}</li>`).join('')}</ul><strong>${owned?'✓ 仲間になった':ready?'封印が解けた · 出会える':'まだ眠っている'}</strong><div class="ad-action-row">${b('legend-preview','姿を見る',`data-id="${c.id}"`)}${b('legend-go',state.current===c.region?'この地域で探す':'✈ '+REGION_BY_ID[c.region].name,`data-id="${c.id}" ${ready?'':'disabled'}`)}</div></article>`}).join('')}</div>`;}
 }
 body.addEventListener('click',e=>{const el=e.target.closest?.('[data-magic-action]');if(!el||el.disabled||state.busy)return;const id=el.dataset.id;try{switch(el.dataset.magicAction){case'section':section=id;notice='';render();break;case'visit':enter();break;case'room':modal.close();break;case'counter':if(interior.go(section))render();break;case'willow':modal.close();ctx.fly('willow');break;case'heal':if(interior.building?.kind!=='park'||!interior.at('care'))throw new Error('屋内の回復カウンターへ来てください。');progress.healAll();world.heal();interior.heal();ctx.speak('Welcome back! Your friends are ready for a new adventure.');notice='✓ 仲間全員の集中力が回復しました。';render();break;case'team':ctx.openTeam();break;case'preview':selectedWand=id;render();break;case'equip':fishing.store.equipWand(id);selectedWand=id;notice=WAND_BY_ID[id].name+'を装備しました。';render();break;case'buy':if(interior.building?.kind!=='park'||!interior.at('wands'))throw new Error('屋内の杖カウンターで購入できます。');fishing.store.buyWand(id);selectedWand=id;fishing.refreshWallet();notice=WAND_BY_ID[id].name+'を購入・装備しました。';render();break;case'legend-preview':ctx.showCreature(id);break;case'legend-go':{const c=CREATURE_BY_ID[id];if(!available(c))throw new Error('伝説の出現条件を確認しよう。');modal.close();if(state.current!==c.region)ctx.fly(c.region);else ctx.seek(id);break;}}}catch(error){toast(error.message)}});
 function available(c){return !LEGEND_BY_ID[c.id]||rpg.state.caught.includes(c.id)||legendGoals(c,progress.state).every(g=>g.done);}
 return {open,world,interior,enter,interact,wallet,available,conditionLabel:c=>LEGEND_BY_ID[c.id]?legendGoals(c,progress.state).map(g=>(g.done?'✓ ':'○ ')+g.text).join(' / '):'',update(t,dt){interior.update(t,dt,progress.settingsSnapshot().reduced);world.update(t,dt,wallet().wand,progress.settingsSnapshot().reduced)},close(){notice=''}};
}
